<script setup>
import {computed,ref,watch} from 'vue';
import {itemRelations} from '../../domain/item-relations.js';
const props=defineProps({record:Object,data:Object});
const tab=ref('profile');watch(()=>props.record?.id,()=>tab.value='profile');
const related=computed(()=>itemRelations(props.record?.id,props.data));
const fields=[['code','Código'],['name','Nombre'],['category','Categoría'],['unit','Unidad de medida'],['location','Ubicación'],['supplierName','Proveedor principal'],['secondSupplierName','Proveedor secundario'],['description','Descripción']];
const money=n=>new Intl.NumberFormat('es-CO',{style:'currency',currency:'COP'}).format(n/100);
const status=s=>({DRAFT:'Borrador',APPROVED:'Aprobada',PENDING:'Pendiente'}[s]||s||'—');
function changeTab(event){const tabs=['profile','orders','movements'];const i=tabs.indexOf(tab.value);if(!['ArrowLeft','ArrowRight','Home','End'].includes(event.key))return;event.preventDefault();tab.value=event.key==='Home'?tabs[0]:event.key==='End'?tabs[2]:tabs[(i+(event.key==='ArrowRight'?1:2))%3];event.currentTarget.parentElement.querySelector('#item-tab-'+tab.value)?.focus();}
</script>
<template>
<div class="item-detail-tabs" role="tablist" aria-label="Información del ítem"><button v-for="[id,label] in [['profile','Ficha del ítem'],['orders','Órdenes de compra'],['movements','Movimientos pendientes']]" :key="id" :id="'item-tab-'+id" type="button" role="tab" :aria-selected="tab===id" :aria-controls="'item-panel-'+id" :tabindex="tab===id?0:-1" @keydown="changeTab" @click="tab=id">{{ label }}<span v-if="id==='orders'"> ({{ related.orders.length }})</span><span v-if="id==='movements'"> ({{ related.movements.length }})</span></button></div>
<section v-if="tab==='profile'" id="item-panel-profile" role="tabpanel" aria-labelledby="item-tab-profile"><dl class="item-detail-fields"><div v-for="[key,label] in fields" :key="key"><dt>{{ label }}</dt><dd>{{ record[key]||'—' }}</dd></div></dl></section>
<section v-if="tab==='orders'" id="item-panel-orders" role="tabpanel" aria-labelledby="item-tab-orders"><div class="sigmyp-account-table-scroll"><table aria-label="Órdenes de compra del ítem"><thead><tr><th>Número</th><th>Proveedor</th><th>Fecha</th><th>Estado</th><th>Cantidad del ítem</th><th>Importe del ítem con impuestos</th></tr></thead><tbody><tr v-for="order in related.orders" :key="order.id"><td>{{ order.number }}</td><td>{{ order.supplierName }}</td><td>{{ order.date }}</td><td>{{ status(order.status) }}</td><td>{{ order.quantity }}</td><td>{{ money(order.totalCents) }}</td></tr><tr v-if="!related.orders.length"><td colspan="6">No hay órdenes de compra relacionadas con este ítem.</td></tr></tbody></table></div></section>
<section v-if="tab==='movements'" id="item-panel-movements" role="tabpanel" aria-labelledby="item-tab-movements"><p class="item-pending-note">Son solicitudes pendientes. No modifican las existencias.</p><div class="sigmyp-account-table-scroll"><table aria-label="Movimientos pendientes del ítem"><thead><tr><th>Fecha</th><th>Tipo</th><th>Cantidad solicitada</th><th>Estado</th><th>Comentarios</th></tr></thead><tbody><tr v-for="movement in related.movements" :key="movement.id"><td>{{ movement.date }}</td><td>{{ movement.movement==='ENTRY'?'Entrada':movement.movement==='EXIT'?'Salida':movement.movement }}</td><td>{{ movement.quantity }}</td><td>{{ status(movement.status) }}</td><td>{{ movement.comments||'—' }}</td></tr><tr v-if="!related.movements.length"><td colspan="5">No hay movimientos pendientes para este ítem.</td></tr></tbody></table></div></section>
</template>
